#!/usr/bin/env node
// Generates Rust + TypeScript protocol code from protocol/schema.json.
// Usage: node tools/protocol-gen.mjs [--check | --fixtures]
//   --fixtures  regenerate, then rewrite protocol/fixtures/*.hex via the Rust encoder.
//   --check  exit 1 if generated files are out of date (used by `just verify`).
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schema = JSON.parse(readFileSync(join(root, "protocol/schema.json"), "utf8"));
const RUST_OUT = join(root, "server/crates/protocol/src/generated.rs");
const TS_OUT = join(root, "web/src/protocol/generated.ts");

const PRIMS = {
  u8: { rs: "u8", ts: "number" },
  u16: { rs: "u16", ts: "number" },
  u32: { rs: "u32", ts: "number" },
  i8: { rs: "i8", ts: "number" },
  i16: { rs: "i16", ts: "number" },
  i32: { rs: "i32", ts: "number" },
  f32: { rs: "f32", ts: "number" },
  f64: { rs: "f64", ts: "number" },
  bool: { rs: "bool", ts: "boolean" },
  string: { rs: "String", ts: "string" },
};

const typeNames = new Set(schema.types.map((t) => t.name));
const fail = (msg) => {
  console.error(`protocol-gen: ${msg}`);
  process.exit(1);
};

// ---- validation ---------------------------------------------------------
function checkRef(ref, where) {
  if (typeof ref === "string") {
    if (!PRIMS[ref] && !typeNames.has(ref)) fail(`${where}: unknown type '${ref}'`);
    return;
  }
  if (!Array.isArray(ref) || ref.length !== 2 || !["vec", "option"].includes(ref[0]))
    fail(`${where}: bad type ref ${JSON.stringify(ref)}`);
  checkRef(ref[1], where);
}
const IDENT = /^[a-z][a-z0-9_]*$/;
const TYPE_IDENT = /^[A-Z][A-Za-z0-9]*$/;
for (const t of schema.types) {
  if (!TYPE_IDENT.test(t.name)) fail(`bad type name ${t.name}`);
  if (t.struct) {
    if (t.struct.length === 0) fail(`${t.name}: empty structs are not allowed (zero-size elements break vec bounds checks)`);
    for (const [f, ty] of t.struct) {
      if (!IDENT.test(f)) fail(`${t.name}.${f}: field names must be snake_case`);
      checkRef(ty, `${t.name}.${f}`);
    }
  } else if (t.enum) {
    for (const [v, fields] of t.enum) {
      if (!TYPE_IDENT.test(v)) fail(`${t.name}::${v}: bad variant name`);
      for (const [f, ty] of fields) {
        if (!IDENT.test(f)) fail(`${t.name}::${v}.${f}: field names must be snake_case`);
        if (f === "type") fail(`${t.name}::${v}: field name 'type' is reserved for the TS tag`);
        checkRef(ty, `${t.name}::${v}.${f}`);
      }
    }
  } else fail(`${t.name}: must have 'struct' or 'enum'`);
}

const camel = (s) => s.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
const HEADER = "GENERATED by tools/protocol-gen.mjs from protocol/schema.json. DO NOT EDIT.";

// ---- Rust ---------------------------------------------------------------
function rsType(ref) {
  if (typeof ref === "string") return PRIMS[ref]?.rs ?? ref;
  return ref[0] === "vec" ? `Vec<${rsType(ref[1])}>` : `Option<${rsType(ref[1])}>`;
}
function rsConst(ty, v) {
  if ((ty === "f32" || ty === "f64") && Number.isInteger(v)) return `${v}.0`;
  return String(v);
}
function genRust() {
  const out = [`// ${HEADER}`, "#![allow(clippy::all)]", "", "use serde::{Deserialize, Serialize};", ""];
  for (const [name, [ty, v]] of Object.entries(schema.constants)) out.push(`pub const ${name}: ${PRIMS[ty].rs} = ${rsConst(ty, v)};`);
  out.push("");
  for (const t of schema.types) {
    if (t.$comment) out.push(`/// ${t.$comment}`);
    out.push("#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]");
    if (t.struct) {
      out.push(`pub struct ${t.name} {`);
      for (const [f, ty] of t.struct) out.push(`    pub ${f}: ${rsType(ty)},`);
      out.push("}");
    } else {
      out.push(`pub enum ${t.name} {`);
      for (const [v, fields] of t.enum) {
        if (fields.length === 0) out.push(`    ${v},`);
        else out.push(`    ${v} { ${fields.map(([f, ty]) => `${f}: ${rsType(ty)}`).join(", ")} },`);
      }
      out.push("}");
    }
    out.push("");
  }
  // test-only: JSON (serde form) -> bincode bytes, for golden fixtures
  out.push("#[cfg(test)]");
  out.push("pub(crate) fn fixture_encode(type_name: &str, value: serde_json::Value) -> Result<Vec<u8>, String> {");
  out.push("    match type_name {");
  for (const t of schema.types)
    out.push(`        "${t.name}" => crate::encode(&serde_json::from_value::<${t.name}>(value).map_err(|e| e.to_string())?).map_err(|e| e.to_string()),`);
  out.push(`        other => Err(format!("unknown type {other}")),`);
  out.push("    }");
  out.push("}");
  return out.join("\n") + "\n";
}

// ---- TypeScript ---------------------------------------------------------
function tsType(ref) {
  if (typeof ref === "string") return PRIMS[ref]?.ts ?? ref;
  return ref[0] === "vec" ? `${tsType(ref[1])}[]` : `${tsType(ref[1])} | null`;
}
function tsWrite(ref, expr) {
  if (typeof ref === "string") return PRIMS[ref] ? `w.${ref}(${expr})` : `write${ref}(w, ${expr})`;
  const inner = (x) => tsWrite(ref[1], x);
  if (ref[0] === "vec") return `w.vec(${expr}, (x) => ${inner("x")})`;
  return `w.option(${expr}, (x) => ${inner("x")})`;
}
function tsRead(ref) {
  if (typeof ref === "string") return PRIMS[ref] ? `r.${ref}()` : `read${ref}(r)`;
  if (ref[0] === "vec") return `r.vec(() => ${tsRead(ref[1])})`;
  return `r.option(() => ${tsRead(ref[1])})`;
}
function genTs() {
  const out = [`// ${HEADER}`, "/* eslint-disable */", 'import { Reader, Writer } from "./codec";', ""];
  for (const [name, [, v]] of Object.entries(schema.constants)) out.push(`export const ${name} = ${v};`);
  out.push("");
  for (const t of schema.types) {
    if (t.$comment) out.push(`/** ${t.$comment} */`);
    if (t.struct) {
      out.push(`export interface ${t.name} {`);
      for (const [f, ty] of t.struct) out.push(`  ${camel(f)}: ${tsType(ty)};`);
      out.push("}");
      out.push(`export function write${t.name}(w: Writer, v: ${t.name}): void {`);
      for (const [f, ty] of t.struct) out.push(`  ${tsWrite(ty, `v.${camel(f)}`)};`);
      out.push("}");
      out.push(`export function read${t.name}(r: Reader): ${t.name} {`);
      out.push("  return {");
      for (const [f, ty] of t.struct) out.push(`    ${camel(f)}: ${tsRead(ty)},`);
      out.push("  };");
      out.push("}");
    } else {
      const alts = t.enum.map(([v, fields]) =>
        `  | { type: "${v}"${fields.map(([f, ty]) => `; ${camel(f)}: ${tsType(ty)}`).join("")} }`,
      );
      out.push(`export type ${t.name} =`, ...alts, ";");
      out.push(`export function write${t.name}(w: Writer, v: ${t.name}): void {`);
      out.push("  switch (v.type) {");
      t.enum.forEach(([v, fields], i) => {
        out.push(`    case "${v}":`);
        out.push(`      w.u32(${i});`);
        for (const [f, ty] of fields) out.push(`      ${tsWrite(ty, `v.${camel(f)}`)};`);
        out.push("      return;");
      });
      out.push("  }");
      out.push("}");
      out.push(`export function read${t.name}(r: Reader): ${t.name} {`);
      out.push("  const tag = r.u32();");
      out.push("  switch (tag) {");
      t.enum.forEach(([v, fields], i) => {
        out.push(`    case ${i}:`);
        out.push(`      return { type: "${v}"${fields.map(([f, ty]) => `, ${camel(f)}: ${tsRead(ty)}`).join("")} };`);
      });
      out.push("    default:");
      out.push(`      throw new Error(\`${t.name}: unknown variant tag \${tag}\`);`);
      out.push("  }");
      out.push("}");
    }
    out.push(`export function encode${t.name}(v: ${t.name}): Uint8Array<ArrayBuffer> {`);
    out.push("  const w = new Writer();");
    out.push(`  write${t.name}(w, v);`);
    out.push("  return w.finish();");
    out.push("}");
    out.push(`export function decode${t.name}(bytes: Uint8Array): ${t.name} {`);
    out.push("  const r = new Reader(bytes);");
    out.push(`  const v = read${t.name}(r);`);
    out.push("  r.end();");
    out.push("  return v;");
    out.push("}");
    out.push("");
  }
  out.push("/** Codec table keyed by type name (used by fixture tests and tooling). */");
  out.push("export const CODECS = {");
  for (const t of schema.types) out.push(`  ${t.name}: { encode: encode${t.name}, decode: decode${t.name} },`);
  out.push("} as const;");
  return out.join("\n") + "\n";
}

// ---- emit ---------------------------------------------------------------
const check = process.argv.includes("--check");
let stale = false;
for (const [path, content] of [
  [RUST_OUT, genRust()],
  [TS_OUT, genTs()],
]) {
  const current = existsSync(path) ? readFileSync(path, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === content) continue;
  if (check) {
    console.error(`protocol-gen: ${path} is out of date — run \`just gen\``);
    stale = true;
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`protocol-gen: wrote ${path}`);
  }
}
if (stale) process.exit(1);

if (process.argv.includes("--fixtures")) {
  const r = spawnSync("cargo", ["test", "-p", "protocol", "golden_fixtures_match"], {
    cwd: join(root, "server"),
    stdio: "inherit",
    env: { ...process.env, VW_UPDATE_FIXTURES: "1" },
  });
  process.exit(r.status ?? 1);
}
